def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(
        r"SUM|MIN|MAX|IF|[A-Z][1-9][0-9]?|[0-9]+|<>|<=|>=|[()+\-*/,=:<>]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }

    def integer(text):
        text = text.strip()
        negative = text.startswith("-")
        if text[:1] in ("-", "+"):
            text = text[1:]
        value = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def parse(text):
        nodes = []
        operators = []
        commas = []
        expecting_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
                return
            right = nodes.pop()
            left = nodes.pop()
            if op == ":":
                nodes.append(("range", left[1], right[1]))
            else:
                nodes.append(("binary", op, left, right))

        for match in token_re.finditer(text):
            token = match.group()

            if token in functions:
                operators.append(token)
                expecting_operand = True
            elif token == "(":
                operators.append("(")
                commas.append(0)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                commas[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = commas.pop() + 1
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = nodes[-count:]
                    del nodes[-count:]
                    nodes.append(("call", function, arguments))
                expecting_operand = False
            elif token[0].isdigit():
                nodes.append(("number", integer(token)))
                expecting_operand = False
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expecting_operand = False
            elif token == "-" and expecting_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and operators[-1] in precedence
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expecting_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(arguments):
        for argument in arguments:
            if argument[0] != "range":
                yield argument
                continue

            first, last = argument[1], argument[2]
            col_low, col_high = sorted((ord(first[0]), ord(last[0])))
            row_low, row_high = sorted((int(first[1:]), int(last[1:])))

            for row in range(row_low, row_high + 1):
                for col in range(col_low, col_high + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    def binary(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    results = {}
    active = set()

    for root in cells:
        if root in results:
            continue

        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in results:
                    values.append(results[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name].strip()
                    tasks.append(("save", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        values.append(integer(content))

            elif kind == "save":
                name = task[1]
                results[name] = values[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    values.append(node[1])
                elif node_kind == "ref":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "call":
                    function, arguments = node[1], node[2]
                    if function == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("eval", arguments[0]))
                    else:
                        tasks.append((
                            "aggregate", function,
                            argument_nodes(arguments), None
                        ))

            elif kind == "negate":
                if not isinstance(values[-1], str):
                    values[-1] = -values[-1]

            elif kind == "left":
                if not isinstance(values[-1], str):
                    left = values.pop()
                    tasks.append(("right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right":
                if not isinstance(values[-1], str):
                    right = values.pop()
                    values.append(binary(task[1], task[2], right))

            elif kind == "choose":
                if not isinstance(values[-1], str):
                    condition = values.pop()
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    values.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append((
                        "collected", function, iterator, accumulated
                    ))
                    tasks.append(("eval", node))

            elif kind == "collected":
                if isinstance(values[-1], str):
                    continue

                value = values.pop()
                function, iterator, accumulated = task[1:]
                if accumulated is None:
                    accumulated = value
                elif function == "SUM":
                    accumulated += value
                elif function == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                tasks.append(("aggregate", function, iterator, accumulated))

    return {name: results[name] for name in cells}
